+    @Override
+    public void beforeEnter(BeforeEnterEvent event) {
+        vetCount = repository.count();
+    }
+
+    private Stream<Vet> fetchVets(Query<Vet, Void> query) {
+        return this.repository.findPage(query.getOffset(), query.getLimit());
+    }
+
+    private int countVets(Query<Vet, Void> query) {
+        return vetCount;
+    }
+
+    private static String specialtiesText(Vet vet) {
+        return vet.specialties().isEmpty() ? NO_SPECIALTIES : String.join(", ", vet.specialties());
+    }
+}
